import java.util.*;
public class OppositeSessionTest {
 static Map<String,Object> a(String c,String t,String s,int n){return Map.of("className",c,"teacher",t,"subject",s,"periods",n);}
 static Map<String,Object> l(String c,String shift,int day,int period,String t,String subject){return Map.of("className",c,"shift",shift,"day",day,"period",period,"teacher",t,"subject",subject,"locked",true);}
 public static void main(String[] args){Map<String,Object> x=new HashMap<>();x.put("classes",List.of(Map.of("name","6/1","shift","morning"),Map.of("name","7/1","shift","afternoon")));x.put("teachers",List.of(Map.of("name","Lan","sessionRule","2"),Map.of("name","Minh","sessionRule","2")));x.put("assignments",List.of(a("6/1","Lan","Hoạt động trải nghiệm",2),a("6/1","Minh","Thể dục",2),a("7/1","Lan","Hoạt động trải nghiệm",2),a("7/1","Minh","Thể dục",2)));x.put("events",List.of());x.put("schedule",List.of(l("6/1","afternoon",1,1,"Lan","Hoạt động trải nghiệm")));
 Map<String,Object> result=new Main.Scheduler(x).run();if(!Boolean.TRUE.equals(result.get("ok")))throw new AssertionError(result);List<?> out=(List<?>)result.get("schedule");for(String c:List.of("6/1","7/1")){List<Map<?,?>> extra=new ArrayList<>();for(Object obj:out){Map<?,?> y=(Map<?,?>)obj;if(c.equals(y.get("className"))&&Main.Scheduler.extraKind((String)y.get("subject"))>0)extra.add(y);}if(extra.size()!=4)throw new AssertionError("Expected four opposite-shift periods: "+extra);int day=(Integer)extra.get(0).get("day");String shift=c.equals("6/1")?"afternoon":"morning";for(Map<?,?> y:extra)if(!shift.equals(y.get("shift"))||!Integer.valueOf(day).equals(y.get("day")))throw new AssertionError("Wrong shift or day");for(int p=1;p<=4;p++){final int num=p;if(extra.stream().noneMatch(y->Integer.valueOf(num).equals(y.get("period"))))throw new AssertionError("Missing period "+p);}if(!extra.get(0).get("subject").equals(extra.get(1).get("subject"))||!extra.get(2).get("subject").equals(extra.get(3).get("subject")))throw new AssertionError("Not double periods");}if(out.stream().map(y->(Map<?,?>)y).noneMatch(y->Boolean.TRUE.equals(y.get("locked"))&&"6/1".equals(y.get("className"))&&Integer.valueOf(1).equals(y.get("day"))&&Integer.valueOf(1).equals(y.get("period"))))throw new AssertionError("Opposite lock was not kept");x.put("schedule",List.of(l("6/1","morning",1,1,"Lan","Hoạt động trải nghiệm")));try{new Main.Scheduler(x).run();throw new AssertionError("Incorrect shift accepted");}catch(IllegalArgumentException expected){}System.out.println("Opposite shifts, same day, four consecutive periods, double lessons and locks passed.");}
}
